/**
 * Pure visual teaching-waveform cursor helpers.
 * Samples are synthetic data generated by waveform-model.js, never bedside measurements.
 */
export function clampRatio(ratio){
  if (!Number.isFinite(ratio)) throw new RangeError("Invalid inspection position");
  return Math.max(0,Math.min(1,ratio));
}
export function ratioFromClientX(clientX,left,width){
  if (![clientX,left,width].every(Number.isFinite)||width<=0)throw new RangeError("Invalid graph bounds");
  return clampRatio((clientX-left)/width);
}
export function inspectAt(samples,ratio){
  if(!Array.isArray(samples)||samples.length<2)throw new RangeError("Missing teaching waveform samples");
  const r=clampRatio(ratio);
  const index=Math.round(r*(samples.length-1));
  const point=samples[index];
  if(!point||!["pressure","flow","volume","time"].every(name=>Number.isFinite(point[name])) ||
     !["mandatory","spontaneous","expiration"].includes(point.phase))throw new RangeError("Invalid waveform sample");
  return {index,ratio:index/(samples.length-1),point};
}
